<script setup lang="ts">
import {computed,reactive,ref,watch,nextTick} from 'vue'
import {Scissors,Check,RotateCcw,Play,Info} from '@lucide/vue'
import type {Revision,Checks,Decision,Job} from '../types'
import GenerationQueue from './GenerationQueue.vue'
import {time,labels} from '../format'
const props=defineProps<{revisions:Revision[];manual:boolean;mediaUrl:string;sourceUrl:string;busy?:boolean;selectedRevision?:string;mediaLoading?:boolean;processing?:boolean;jobs?:Job[]}>()
const emit=defineEmits<{select:[id:string];decision:[value:Decision];export:[];delete:[id:string];deleted:[];resume:[id:string]}>()
const filter=ref('all')
const visible=computed(()=>props.revisions.filter(r=>filter.value==='all'||filter.value==='approved'&&r.review_status==='approved'||filter.value==='review'&&r.review_status==='needs_review'||filter.value==='exported'&&r.exported))
const selected=ref(''),notes=ref(''),sourcePlayer=ref<HTMLVideoElement>(),sourceDetails=ref<HTMLDetailsElement>()
const criteria:{key:keyof Checks;label:string}[]=[{key:'completeness',label:'O pensamento está completo'},{key:'context',label:'O trecho faz sentido fora do vídeo'},{key:'qualifications',label:'Negações, números e ressalvas estão preservados'},{key:'words_and_boundaries',label:'Nenhuma palavra ou argumento foi cortado'},{key:'audiovisual',label:'Revisei áudio, enquadramento e legendas'}]
const checks=reactive<Checks>({completeness:false,context:false,qualifications:false,words_and_boundaries:false,audiovisual:false})
const current=computed(()=>visible.value.find(r=>r.revision_id===(props.selectedRevision||selected.value))||visible.value[0])
const ready=computed(()=>current.value?.technical_pass&&!!props.mediaUrl&&!props.mediaLoading&&criteria.every(c=>checks[c.key])&&!props.busy)
watch(visible,rows=>{if(props.selectedRevision&&rows.some(r=>r.revision_id===props.selectedRevision)){selected.value=props.selectedRevision;return}if(!rows.some(r=>r.revision_id===selected.value)&&rows.length){selected.value=rows[0].revision_id;emit('select',selected.value)}},{immediate:true})
watch(()=>[current.value?.revision_id,current.value?.content_hash],()=>{for(const c of criteria)checks[c.key]=false;notes.value=current.value?.notes||''})
function choose(id:string){selected.value=id;emit('select',id)}
function decide(decision:'approved'|'rejected'){if(!current.value?.content_hash||(decision==='approved'&&!ready.value))return;emit('decision',{revision_id:current.value.revision_id,decision,checks:{...checks},notes:notes.value,content_hash:current.value.content_hash})}
function listenPause(us:number){if(sourceDetails.value)sourceDetails.value.open=true;if(sourcePlayer.value){sourcePlayer.value.currentTime=Math.max(0,us/1e6-2);sourcePlayer.value.play().catch(()=>{})}}
function context(){if(sourcePlayer.value){sourcePlayer.value.currentTime=Math.max(0,(current.value?.start_us||0)/1e6-30);sourcePlayer.value.play().catch(()=>{})}}
</script>
<template>
  <div v-if="manual" class="manual-review"><div class="notice"><Info :size="19"/><div><strong>Prévia manual de renderização</strong><p>Este trecho é um teste técnico. Não foi selecionado pelo Gemini e não está aprovado editorialmente.</p></div></div><video v-if="mediaUrl" class="manual-player" :src="mediaUrl" controls preload="metadata" playsinline></video></div>
  <button v-if="!manual" type="button" class="button secondary" @click="$emit('deleted')">Lixeira de cortes</button><div v-if="!manual&&!revisions.length" class="empty-state cuts-empty"><span class="empty-icon"><Scissors :size="28"/></span><h2>Nenhum corte disponível</h2><p>A transcrição pode ser consultada. Na aba Análise, escolha propostas e gere prévias. Cada prévia aparece aqui após a verificação técnica.</p><span class="subtle">Nenhuma seleção é aprovada automaticamente.</span></div>
  <div v-if="!manual" class="cuts-filters" aria-label="Filtrar cortes"><button v-for="([id,label]) in [['all','Todos'],['generation','Em geração'],['review','Para revisar'],['approved','Aprovados'],['exported','Exportados']]" :key="id" :class="{selected:filter===id}" :aria-pressed="filter===id" @click="filter=id">{{label}}</button></div><GenerationQueue v-if="!manual&&['all','generation'].includes(filter)" :jobs="jobs||[]" @resume="$emit('resume',$event)"/><p v-if="filter!=='generation'&&revisions.length&&!visible.length" class="notice">Nenhum corte neste estado.</p><p v-if="filter==='generation'&&!jobs?.some(j=>j.operation==='render'&&j.progress?.items?.length)" class="notice">Nenhuma prévia em geração.</p><div v-if="!manual&&visible.length" class="review-grid">
    <aside class="clip-list"><h3>Cortes <span>{{revisions.length}}</span></h3><button v-for="(r,index) in visible" :key="r.revision_id" class="clip-item" :class="{selected:current?.revision_id===r.revision_id}" @click="choose(r.revision_id)"><span class="clip-number">{{index+1}}</span><div><strong>{{r.title}}</strong><small>{{time(r.start_us)}} – {{time(r.end_us)}} · {{time(r.duration_us)}}</small><span class="status-pill" :data-status="r.review_status"><i></i>{{labels[r.review_status]||r.review_status}}</span></div></button><button class="button secondary full" :disabled="busy||processing||!revisions.some(r=>r.review_status==='approved')" @click="$emit('export')">Exportar aprovados</button></aside>
    <div class="clip-preview"><video v-if="mediaUrl" :src="mediaUrl" controls preload="metadata" playsinline></video><div v-else class="video-unavailable">Prévia indisponível</div><button type="button" class="button small secondary" :disabled="busy||processing" data-action="delete-clip" @click="current&&$emit('delete',current.revision_id)">Excluir corte</button><p class="preview-label">{{current?.title}}</p><p class="subtle">{{current?.rationale}}</p><p v-if="current?.removed_silence_us" class="subtle">{{(current.removed_silence_us/1e6).toFixed(2)}} s de silêncios reduzidos · {{current.pause_removals?.length}} junção(ões)</p><details v-if="current?.pause_removals?.length"><summary>Revisar silêncios removidos</summary><button v-for="(pause,index) in current.pause_removals" :key="pause.source_start_us" class="button small secondary" @click="listenPause(pause.source_start_us)">Junção {{index+1}} · original {{time(pause.source_start_us)}} – {{time(pause.source_end_us)}}</button></details><p v-for="warning in current?.warnings.filter(w=>w!=='Editorial integrity requires human review; technical checks do not prove meaning.')" :key="warning" class="subtle">{{warning}}</p><details ref="sourceDetails"><summary>Conferir no original</summary><video ref="sourcePlayer" :src="sourceUrl" controls preload="none"></video><button class="button small secondary" @click="context"><Play :size="13"/>Ouvir com 30 s de contexto</button></details></div>
    <form class="review-checks" @submit.prevent="decide('approved')"><h3>Revisão editorial</h3><p>Ouça o corte e confira o contexto antes de aprovar.</p><div v-if="!current?.technical_pass" class="notice error">A verificação técnica falhou. Gere a prévia novamente.</div><label v-for="criterion in criteria" :key="criterion.key" class="check-row"><input type="checkbox" v-model="checks[criterion.key]"/><span>{{criterion.label}}</span></label><label class="field">Notas<textarea v-model="notes" rows="3" placeholder="Observações desta revisão"/></label><button type="button" @click="decide('approved')" data-action="approve" class="button primary full" :disabled="!ready"><Check :size="17"/>Aprovar corte</button><button type="button" class="button secondary full" :disabled="busy||!current?.technical_pass" @click="decide('rejected')"><RotateCcw :size="16"/>Rejeitar corte</button></form>
  </div>
</template>

